mapper.insert:
insert into customer_order (
    order_number, goods_id, user_id, business_id, product_name, product_img,
    quantity, unit_price, total_price, status
) values (
    #{orderNumber}, #{goodsId}, #{userId}, #{businessId}, #{productName}, #{productImg},
    #{quantity}, #{unitPrice}, #{totalPrice}, #{status}
)

mapper.select:
select customer_order.*, customer.name as customerName, business.name as businessName
from customer_order
left join user customer on customer_order.user_id = customer.id
left join business on customer_order.business_id = business.id

    and customer_order.id = #{id}
    and customer_order.user_id = #{userId}
    and customer_order.business_id = #{businessId}
    and customer_order.status = #{status}

order by customer_order.created_at desc, customer_order.id desc

mapper.update:
update customer_order
set status = #{status}
where id = #{id}
